/// State the shared components keep between frames (`App::widgets`): each
/// track list's selection, the tooltip layer, shelves' scroll edges and the
/// favourite hearts' pop animation.
#[derive(Default)]
pub struct Widgets {
    pub lists: track_select::Lists,
    pub tooltip: tooltip::State,
    pub shelves: shelf::Shelves,
    pub numbers: blocks::Numbers,
}

use rune::{Color, El, Family, Icon, TextStyle, icon, text};

/// Runs before each frame for the shared components: tooltips waiting out
/// their delay and counters rolling.
pub fn poll(app: &mut crate::app::App, clock: f64, tx: &mut rune::Tx) -> bool {
    let a = tooltip::poll(app, clock);
    let b = blocks::poll_numbers(app, clock, tx);
    a || b
}

/// `box-shadow: var(--shadow-md)` on any element: `el.shadow_md(t)`.
pub trait ShadowMd {
    fn shadow_md(self, t: &crate::theme::Theme) -> Self;
}

impl ShadowMd for El {
    fn shadow_md(self, t: &crate::theme::Theme) -> El {
        let a = Color::BLACK.alpha(t.c.shadow_md_alpha);
        self.box_shadow(rune::Shadow { x: 0.0, y: 4.0, blur: 6.0, spread: -1.0, color: a, inset: false })
            .box_shadow(rune::Shadow { x: 0.0, y: 2.0, blur: 4.0, spread: -2.0, color: a, inset: false })
    }
}

/// CSS `line-height: 1.45` (the body's), which every text inherits unless a
/// rule says otherwise.
pub const LH: f32 = 1.45;

/// Geist at `size` px and `weight`, with the body's line height.
pub fn font(size: f32, weight: f32) -> TextStyle {
    TextStyle { line_height: (size * LH * 100.0).round() / 100.0, ..TextStyle::new(size, weight) }
}

/// Geist Mono (`.mono`, `--font-mono`).
pub fn mono(size: f32, weight: f32) -> TextStyle {
    TextStyle { family: Family::Mono, ..font(size, weight) }
}

/// `font-variant-numeric: tabular-nums`.
pub fn tnum(style: TextStyle) -> TextStyle {
    style.features("'tnum' 1")
}

/// A single line that ends in "…" when it doesn't fit
/// (`white-space: nowrap; overflow: hidden; text-overflow: ellipsis`).
pub fn line(s: impl Into<String>, style: TextStyle, color: Color) -> El {
    text(s).font(style).color(color).truncate().shrink()
}

/// `text-wrap: balance` for text that breaks anywhere: the narrowest width
/// up to `max` at which `s` in `style` is no taller than at `max`, so its
/// lines come out even. One line keeps `max`.
pub fn balanced_width(s: &str, style: TextStyle, max: f32) -> f32 {
    let opts = rune::text::RichLayoutOptions::new().wrap_anywhere();
    let height = |w: f32| rune::text::measure_with(s, &[], style, Some(w), opts).1;
    let h = height(max);
    if h <= style.line_height * 1.5 {
        return max;
    }
    let (mut lo, mut hi) = (0.0f32, max);
    for _ in 0..14 {
        let mid = (lo + hi) / 2.0;
        if height(mid) > h + 0.5 { lo = mid } else { hi = mid }
    }
    hi.ceil().min(max)
}

/// A single line of text laid out at its CSS line height `lh` exactly.
/// Rune rounds a text's box up to whole pixels (17.4 → 18), which adds up
/// down a column of lines; the box around it keeps the fractional height,
/// so what follows sits where the browser puts it.
pub fn exact(e: El, lh: f32) -> El {
    rune::el().h(lh).min_w(0.0).child(e)
}


/// Text a flex row centres vertically (`align-items: center`). Rune rounds
/// a text box up to whole pixels (20.3 → 21), so centring puts its top
/// half the rounding above where the browser centres the 20.3 px box, and
/// both engines then snap the baseline to a whole pixel: often the one
/// above Chromium's. This nudges the glyphs back by that half (drawing
/// only; layout keeps the rounded box).
pub fn centred(e: El, style: TextStyle) -> El {
    centred_lh(e, if style.line_height > 0.0 { style.line_height } else { style.size * 1.25 })
}

/// [`centred`] for a line `lh` px tall.
pub fn centred_lh(e: El, lh: f32) -> El {
    e.offset(0.0, (lh.ceil() - lh) / 2.0)
}

/// Where Chromium puts the baseline of a line of Geist at `size` px in its
/// `lh`-tall box: the font's ascent (1.005 em) and descent (0.295 em) each
/// rounded to whole pixels, the half-leading floored. Lines of different
/// sizes that share a baseline, and `vertical-align: middle` boxes (half
/// the 0.53 em x-height above it), line up by it.
pub fn css_baseline(size: f32, lh: f32) -> f32 {
    let (ascent, descent) = ((1.005 * size).round(), (0.295 * size).round());
    ascent + ((lh - ascent - descent) / 2.0).floor()
}

/// CSS `ch` units: `n` advances of `style`'s "0" (`max-width: 60ch`).
pub fn ch(n: f32, style: TextStyle) -> f32 {
    rune::text::advance("0", style) * n
}

/// `.skeleton-text`: a bar 0.75 em tall at `vertical-align: middle` in a
/// line of `size` px type `lh` tall, `frac` of the line's width.
pub fn skeleton_line(t: &crate::theme::Theme, size: f32, lh: f32, frac: f32) -> El {
    rune::el().w_full().h(lh).child(skeleton_bar(t, size, lh).w_frac(frac))
}

/// [`skeleton_line`] with a bar `w` wide (`width: 4ch`).
pub fn skeleton_line_w(t: &crate::theme::Theme, size: f32, lh: f32, w: f32) -> El {
    rune::el().w_full().h(lh).child(skeleton_bar(t, size, lh).w(w))
}

fn skeleton_bar(t: &crate::theme::Theme, size: f32, lh: f32) -> El {
    let top = css_baseline(size, lh) - 0.265 * size - 0.375 * size;
    rune::el().absolute(0.0, top).h(0.75 * size).radius(t.radius_sm()).fill(t.c.muted)
}

/// Text that ends at its box's right edge (`text-align: right`). Rune
/// sizes a text's box to its advance rounded up to a whole pixel, which
/// would leave the glyphs up to a pixel short of the edge; this moves them
/// back onto it.
pub fn text_end(s: impl Into<String>, style: TextStyle, color: Color) -> El {
    let s = s.into();
    let e = text(s.clone()).font(style).color(color);
    nudge_end(e, &s, style)
}

/// [`text_end`]'s nudge for a text element `e` already built from `s`
/// (a live label): the glyphs move right by the rounding of its advance.
pub fn nudge_end(e: El, s: &str, style: TextStyle) -> El {
    let w = rune::text::advance(s, style);
    e.offset(w.ceil() - w, 0.0)
}

/// [`nudge_end`] for text centred in its box: half the rounding.
pub fn nudge_centre(e: El, s: &str, style: TextStyle) -> El {
    let w = rune::text::advance(s, style);
    e.offset((w.ceil() - w) / 2.0, 0.0)
}

/// A lucide icon `size` px square in `color` (`currentColor`).
pub fn ico(i: &'static Icon, size: f32, color: Color) -> El {
    icon(i, size).color(color)
}

/// The height CSS gives `s` set in `style` and wrapped at `max_width`: whole
/// lines of `line-height`, fractions kept. Rune rounds each text box up to
/// whole pixels (a 20.3 px line takes 21), which moves everything under it;
/// pin a text's box with `.h(css_text_h(..))` where that matters.
pub fn css_text_h(s: &str, style: TextStyle, max_width: Option<f32>) -> f32 {
    css_text_h_with(s, style, max_width, rune::text::RichLayoutOptions::default())
}

/// [`css_text_h`] for text laid out with `opts`: the text an element draws
/// with `.wrap_anywhere()` (`overflow-wrap: anywhere`) measures with
/// `RichLayoutOptions::new().wrap_anywhere()`.
pub fn css_text_h_with(s: &str, style: TextStyle, max_width: Option<f32>, opts: rune::text::RichLayoutOptions) -> f32 {
    if style.line_height <= 1.0 {
        return rune::text::measure_with(s, &[], style, max_width, opts).1;
    }
    css_lines(s, &[], style, max_width, opts) as f32 * style.line_height
}

/// How many lines `s` (with `spans`) takes in `style` wrapped at
/// `max_width` with `opts`: at least one.
pub fn css_lines(s: &str, spans: &[rune::text::Span], style: TextStyle, max_width: Option<f32>, opts: rune::text::RichLayoutOptions) -> usize {
    let (_, h) = rune::text::measure_with(s, spans, style, max_width, opts);
    // `h` is ceil(lines × lh), so with lh > 1 the floor gives the lines back.
    ((h / style.line_height.max(1.0) + 1e-3).floor() as usize).max(1)
}

/// `TextStyle` with an explicit line height in px.
pub fn with_lh(style: TextStyle, lh: f32) -> TextStyle {
    TextStyle { line_height: lh, ..style }
}

/// A CSS border: drawn over the element's own fill, as the browser paints a
/// border over `background` (rune's `.border` replaces the fill under it, so
/// a translucent ring would show the parent instead). Call before adding the
/// element's other children; CSS borders also take layout space, so add the
/// width to the element's padding.
pub fn css_border(e: El, width: f32, color: Color, radius: f32) -> El {
    e.child(
        rune::el()
            .pin(Some(0.0), Some(0.0), Some(0.0), Some(0.0))
            .radius(radius)
            .border(width, color)
            .inert(),
    )
}

/// `border-bottom`: a hairline along the element's bottom edge.
pub fn css_border_bottom(e: El, width: f32, color: Color) -> El {
    e.child(rune::el().pin(Some(0.0), None, Some(0.0), Some(0.0)).h(width).fill(color).inert())
}

/// `border-top`: a hairline along the element's top edge (add `width` to
/// its top padding, as for [`css_border`]).
pub fn css_border_top(e: El, width: f32, color: Color) -> El {
    e.child(rune::el().pin(Some(0.0), Some(0.0), Some(0.0), None).h(width).fill(color).inert())
}

/// CSS transitions as rune curves.
pub mod motion {
    use rune_motion::{Anim, Curve, Easing, Spring};

    /// Layout and colour changes that aren't given a curve of their own: the
    /// length of the web's common 200 ms transitions, without a long tail.
    pub const LAYOUT: Spring = Spring::new(0.2, 0.0);

    /// `transition: <ms>ms ease`.
    pub fn ease(ms: f32) -> Anim {
        Anim::new(Curve::tween(ms / 1000.0, Easing::EASE))
    }
    /// `--ease-out`: cubic-bezier(0.23, 1, 0.32, 1).
    pub fn ease_out(ms: f32) -> Anim {
        Anim::new(Curve::tween(ms / 1000.0, Easing::cubic(0.23, 1.0, 0.32, 1.0)))
    }
    /// The sidebar's grid transition: cubic-bezier(0.22, 1, 0.36, 1).
    pub fn shell(ms: f32) -> Anim {
        Anim::new(Curve::tween(ms / 1000.0, Easing::cubic(0.22, 1.0, 0.36, 1.0)))
    }
}

/// Text that may wrap, held to the CSS height of its lines (`lh` each).
/// Rune rounds a text box's height up to whole pixels, so a stack of
/// fractional line heights (16.8, 20.3) drifts down a pixel every few rows;
/// this reads the text's line count from the last layout and sizes a box to
/// `lines × lh`. `key` must be unique in the view.
pub fn snug_lines(key: &str, t: El, lh: f32) -> El {
    let n = rune::memo::layout_with(key, move |r| (r[3] / lh).round().max(1.0) as u32).unwrap_or(1);
    rune::col().w_full().min_w(0.0).h(n as f32 * lh).child(t.key(key).w_full())
}
